index.content:
RSV:= (HHV(HIGH,N)-CLOSE)/(HHV(HIGH,N)-LLV(LOW,N))*100;
LWR1:SMA(RSV,M1,1);
LWR2:SMA(LWR1,M2,1);

BIAS1 :(CLOSE-MA(CLOSE,N1))/MA(CLOSE,N1)*100;
BIAS2 :(CLOSE-MA(CLOSE,N2))/MA(CLOSE,N2)*100;
BIAS3 :(CLOSE-MA(CLOSE,N3))/MA(CLOSE,N3)*100;

LC:=REF(CLOSE,1);
AA:=ABS(HIGH-LC);
BB:=ABS(LOW-LC);
CC:=ABS(HIGH-REF(LOW,1));
DD:=ABS(LC-REF(OPEN,1));
R:=IF(AA>BB AND AA>CC,AA+BB/2+DD/4,IF(BB>CC AND BB>AA,BB+AA/2+DD/4,CC+DD/4));
X:=(CLOSE-LC+(CLOSE-OPEN)/2+LC-REF(OPEN,1));
SI1:=16*X/R*MAX(AA,BB);
ASI:SUM(SI1,0);
MA6:MA(ASI,6);

TR:=EMA(MAX(MAX(HIGH-LOW,ABS(HIGH-REF(CLOSE,1))),ABS(REF(CLOSE,1)-LOW)),N);
HD :=HIGH-REF(HIGH,1);
LD :=REF(LOW,1)-LOW;
DMP:=EMA(IF(HD>0 AND HD>LD,HD,0),N);
DMM:=EMA(IF(LD>0 AND LD>HD,LD,0),N);
PDI: DMP*100/TR;
MDI: DMM*100/TR;
ADX: EMA(ABS(MDI-PDI)/(MDI+PDI)*100,M);
ADXR:EMA(ADX,M);

TR:=EMA(EMA(EMA(CLOSE,N),N),N);
TRIX:(TR-REF(TR,1))/REF(TR,1)*100;
MATRIX:MA(TRIX,9) ;

AA:=MA((OPEN+HIGH+LOW+CLOSE)/4,60);
放量:=MA(VOL,5)>MA(VOL,60);
涨停:=(CLOSE/REF(CLOSE,1))>1.095 AND CLOSE=HIGH;
下降波浪:AA,LINETHICK1,COLORBLUE;
上升波浪:IF(AA>REF(AA,1),AA,DRAWNULL),LINETHICK1,COLORMAGENTA;
下降波浪1:=IF(AA<=REF(AA,1),AA,DRAWNULL);
快线:=EMA(MA((3*CLOSE+2*OPEN+HIGH+LOW)/7,4),2);
STICKLINE(快线>=REF(快线,1),快线,REF(快线,1),8,0),COLORRED,NOTITLE;
STICKLINE(快线<REF(快线,1),快线,REF(快线,1),8,0),COLORCYAN,NOTITLE;

STICKLINE(放量=1 AND 快线>AA AND 快线>REF(快线,1),REF(快线,1),AA,1,0),COLORYELLOW,NOTITLE;
STICKLINE(放量=1 AND 快线>AA AND 快线<=REF(快线,1),快线,AA,1,0),COLORYELLOW,NOTITLE;
STICKLINE(CLOSE/REF(CLOSE,1)>1.095 AND CLOSE=HIGH,快线,REF(快线,1),8,0),COLORMAGENTA,NOTITLE;
金叉周期:=BARSLAST(CROSS(快线,AA)=1)+1;

DRAWICON(快线>AA AND  上升波浪<>DRAWNULL  AND  放量=1 AND REF(放量,1)=0 AND 快线>=REF(快线,1),AA,92),NOTITLE;

DRAWICON(快线>AA AND 上升波浪<>DRAWNULL AND REF(下降波浪1,1)<>DRAWNULL AND 放量=1 AND 快线>=REF(快线,1),AA,92),NOTITLE;

DRAWICON(CROSS(快线,AA) AND  上升波浪<>DRAWNULL AND 放量=1 AND 快线>=REF(快线,1),AA,92),NOTITLE;

ZCZDATE:=1200824;
主力攻击线:(MA(CLOSE,3)+MA(CLOSE,6)+MA(CLOSE,9))/3,COLORWHITE;
主力控盘线:(MA(CLOSE,5)+MA(CLOSE,10)+MA(CLOSE,15)+MA(CLOSE,20)+MA(CLOSE,25)+MA(CLOSE,30))/6,COLORYELLOW,LINETHICK2;
IF(主力攻击线>REF(主力攻击线,1) AND 主力攻击线>主力控盘线,主力攻击线,DRAWNULL),COLORRED,NOTITLE;
涨幅:=CLOSE/REF(CLOSE,1)-1;
涨停:=涨幅>=0.09 AND CLOSE=HIGH;
实体:=CLOSE>LOW;
成交额:=AMOUNT>=REF(HHV(AMOUNT,10),1);
RSV:=(CLOSE-LLV(LOW,34))/(HHV(HIGH,34)-LLV(LOW,34))*100;
K:=SMA(RSV,3,1);
乖离率:=(CLOSE/主力攻击线-1)*100;

{注册板}
M1:=4;
M2:=6;
M3:=9;
M4:=13;
M5:=18;
M6:=24;
PBX1:=(EMA(CLOSE,M1)+EMA(CLOSE,M1*2)+EMA(CLOSE,M1*4))/3;
PBX2:=(EMA(CLOSE,M2)+EMA(CLOSE,M2*2)+EMA(CLOSE,M2*4))/3;
PBX3:=(EMA(CLOSE,M3)+EMA(CLOSE,M3*2)+EMA(CLOSE,M3*4))/3;
PBX4:=(EMA(CLOSE,M4)+EMA(CLOSE,M4*2)+EMA(CLOSE,M4*4))/3;
PBX5:=(EMA(CLOSE,M5)+EMA(CLOSE,M5*2)+EMA(CLOSE,M5*4))/3;
PBX6:=(EMA(CLOSE,M6)+EMA(CLOSE,M6*2)+EMA(CLOSE,M6*4))/3;
多头形态:=C>PBX1 AND PBX1>REF(PBX1,1) AND PBX1>PBX2 AND PBX2>PBX3 AND PBX3>PBX4 AND PBX5>REF(PBX5,1);
综合价格:=(2*C+H+L+O)/5;
现价新高:=综合价格>=REF(HHV(综合价格,20),1);
当日涨幅:=(CLOSE-REF(CLOSE,1))/REF(CLOSE,1)*100>=5.00 AND NOT(H=L) AND O/REF(C,1)<1.10;
低点幅度:=C/LLV(L,120)>=1.20;
高点幅度:=C/HHV(H,60)>=0.80;
上影线:=C/H>=0.95;
爆量:=EMA(VOL,3)/EMA(VOL,60)>=1.5 OR VOL>REF(HHV(VOL,5),1);
XG:=FILTER(多头形态 AND 现价新高 AND 当日涨幅 AND 低点幅度 AND 高点幅度  AND 爆量 AND 上影线,20);
DRAWICON(XG=1 ,LOW,60),NOTITLE;

ZY2:=VOL/INDEXV*1000;
量比:ZY2;
MA5:MA(ZY2,5);
MA10:MA(ZY2,10);

VAR1:=MA((VOL-REF(VOL,1))/REF(VOL,1),5);
VAR2:=(CLOSE-MA(CLOSE,24))/MA(CLOSE,24)*100;
MY: VAR2*(1+VAR1);
SHT: MY, COLORSTICK;
SHTMA: MA(SHT,N);

VAR1:=(100 - ((90 * (HHV(HIGH,14) - CLOSE)) / (HHV(HIGH,14) - LLV(LOW,14))));
VAR2:=(100 - ((90 * (HHV(HIGH,14) - CLOSE)) / (HHV(HIGH,14) - LLV(LOW,14))));
VAR3:=(100 - MA(((100 * (HHV(HIGH,6) - CLOSE)) / (HHV(HIGH,6) - LLV(LOW,6))),34));
DIR1:=ABS(CLOSE-REF(CLOSE,5));
VIR1:=SUM(ABS(CLOSE-REF(CLOSE,1)),5);
ER1:=DIR1/VIR1;
CS1:=ER1*(0.8-2/8)+2/8;
CQ1:=CS1*CS1;
AMA1:=EMA(DMA(CLOSE,CQ1),2);
DIR2:=ABS(CLOSE-REF(CLOSE,10));
VIR2:=SUM(ABS(CLOSE-REF(CLOSE,1)),10);
ER2:=DIR2/VIR2;
CS2:=ER2*(0.8-2/24)+2/24;
CQ2:=CS2*CS2;

{缺省为1,  1 --下跌(绿色);2--上涨(红色),3-上涨盘整(黄色),4--下跌盘整(兰色)}

工作线:EMA(DMA(CLOSE,CQ2),2),COLOR871F78;
R:=工作线/REF(工作线,1)*1000;
R1:=INTPART(R); 
XJ:= IF(R1<0.997*1000 OR R1=0.997*1000,1,0);
SS:=IF(R1>1.001*1000,2,0);
PZ:= IF(R1>0.997*1000 AND R1<1.001*1000,3,0);
{判断上一阶段的状态}
D1:=BARSLAST(XJ=1);
D2:=BARSLAST(SS=2);

SSPZ0:=IF((D1>D2) AND PZ=3,3,0);
XJPZ0:=IF((D1<D2) AND PZ=3,4,0);
D3:=BARSLAST(SSPZ0=3);
D4:=BARSLAST(XJPZ0=4);

{如果前面仅上涨两天,则视为趋势未变，当前状态仍为 下降调整}
SSPZ:=IF((SSPZ0=3) AND (D4<4),4,SSPZ0);
XJPZ:=IF((XJPZ0=4) AND (D3<4),3,XJPZ0);

SR0:=IF((SSPZ0=3) AND (D4<4),1,0);
XR0:=IF((XJPZ0=4) AND (D3<4),1,0);
D5:=BARSLAST(SR0=1);
D6:=BARSLAST(XR0=1);

SSPZR:=IF((SSPZ0=3) AND (D5<D1 AND D5<D2),4,SSPZ0);
XJPZR:=IF((XJPZ0=4) AND (D6<D1 AND D6<D2),3,XJPZ0);

RED:(SS=2);
BLUE:((XJPZ=4 OR SSPZ=4 OR (SSPZ=3 AND SSPZR=4)));
GREEN:(XJ=1);
YELLOW:(((SSPZ=3 AND SSPZR=3) OR XJPZ=3  OR (XJPZ=4 AND XJPZR=3)));

{大盘抄底}
Z:=MA(C,120);
VAR7:=(MA(C,5)-Z)/Z;
VAR8:=MA((CLOSE-LLV(LOW,20))/(HHV(HIGH,20)-LLV(LOW,20))*100,3);
CD:(CLOSE>Z AND REF(VAR8,1)<30 AND VAR8>REF(VAR8,1) AND REF(VAR8,1)<REF(VAR8,2)) OR (REF(VAR8,1)<7 AND VAR8>REF(VAR8,1) AND REF(VAR8,1)<REF(VAR8,2) AND VAR7<-0.1) OR   
(CROSS(VAR8,5) AND VAR7<-0.3);

{大盘逃顶}
VAR9:=(MA(H,5)-Z)/Z;
VAR10:=MA((CLOSE-LLV(LOW,10))/(HHV(HIGH,10)-LLV(LOW,10))*100,3);
TD:(CROSS(95,VAR10) AND VAR9>0.3,1.01*HIGH) OR ( CROSS(93,VAR10) AND HHV(H,30)/LLV(L,30)>1.1 AND REF(Z,1)/Z>0.997) OR (CLOSE<Z AND Z<REF(Z,1) AND REF(VAR10,1)>90 AND VAR10<REF(VAR10,1) AND REF(VAR10,1)>REF(VAR10,2));

MAVOL1:=MA(AMOUNT,5),COLORWHITE;
MAVOL2:=MA(AMOUNT,20),COLORYELLOW,LINETHICK2;
B:=MAVOL1>MAVOL2;
G:=MA(AMOUNT,20)>REF(MA(AMOUNT,20),1),NODRAW;
量1:=IF(B,30,0);
量2:=IF(G,25,0);
量3:=IF(AMOUNT>MA(AMOUNT,20),10,0);
价1:=IF(C>MA(C,10),10,0);
价2:=IF(MA(C,10)>REF(MA(C,10),1),15,0);
价3:=IF(C>REF(C,1),10,0);
MA10:MA(C,10),COLORYELLOW;
今日总分:量1+量2+量3+价1+价2+价3,COLORRED,NODRAW;
不开:=今日总分>70 AND C<REF(C,1);
DRAWTEXT(今日总分>70 AND NOT(不开),MA10,'多'),COLORRED,NOTITLE;
DRAWTEXT(今日总分<=50,MA10,'空'),COLORGREEN,NOTITLE;
DRAWTEXT((今日总分>50 AND 今日总分<=70) OR(今日总分>70 AND 不开),MA10,'转'),NOTITLE;

BIAS :=(CLOSE-MA(CLOSE,5))/MA(CLOSE,5)*100;
七天乖离:=MA(BIAS,7);
DM:=REF(COUNT(BIAS<3.3,7),1)>=3;
BD1:=((REF(BIAS,1)<REF(LLV(BIAS,7),2) AND REF(BIAS,1)<3.5 ) OR REF(BIAS,1)<1.3);
QD1:=DM AND O>=REF(C,1)*1.04 AND  ( O>=REF(HHV(H,6),1) OR  O>=REF(HHV(C,6),1))  AND REF(BIAS,1)<6;
QD2:=BD1 AND O>=REF(C,1)*1.04 AND  ( O>=REF(HHV(H,6),1) OR  O>=REF(HHV(C,6),1)) AND REF(BIAS,1)<6;
BINGDIAN:=(H-C)/REF(C,1)>0.04 AND C<REF(C,1);
QD3:=REF(L,1)<REF(MA(C,5),1)*1.015  AND O>=REF(C,1)*1.04;
变:=QD1 OR QD2 OR QD3;
MKV:=MKT_FT_VALUE(3003,'_6昨连板今红率',0)<0.4;
启:=(QD1 OR QD2 OR QD3) AND MKV;
DRAWTEXT(变,1.02*(H),'变'),COLORYELLOW,NOTITLE;
DRAWTEXT(启 AND NOT(变),1.02*(H),'启'),COLORRED,NOTITLE;
DRAWTEXT(启 AND 变,1.04*(H),'启'),COLORRED,NOTITLE;
MA5:MA(C,5),NOTITLE;

RSV:=(CLOSE-LLV(LOW,N))/(HHV(HIGH,N)-LLV(LOW,N))*100;
K:=SMA(RSV,M1,1);
D:=SMA(K,M2,1);
KD:CROSS(K,D)  AND K<20;

MID :=  MA(CLOSE,N);
UPPER:= MID+S*STD(CLOSE,N);
LOWER:= MID-S*STD(CLOSE,N);
CROSS(CLOSE,LOWER);

RSV:= (CLOSE-LLV(LOW,N))/(HHV(HIGH,N)-LLV(LOW,N))*100;
K:=SMA(RSV,N1,1);
D:=SMA(K,N2,1);
CROSS(D,K) AND D>N3;
